
SELECT r.id, p.id FROM roles r CROSS JOIN permissions p
WHERE r.is_system = 1 AND p.code IN ('machinery.view','machinery.create','machinery.update','machinery.delete','maintenance.view','maintenance.create','maintenance.update','maintenance.delete','fuel.view','fuel.create','fuel.update','fuel.delete','procurement.view','procurement.create','procurement.update','procurement.delete','budgets.view','budgets.create','budgets.update','budgets.delete','production.view','production.create','labor.view','labor.create','costs.view','costs.create','inventory.view','inventory.create','masters.view','masters.create');
